package main

import "core:fmt"
import "core:os"
import "core:strings"

main :: proc() {
    buf: [256]byte
    n, err := os.read(os.stdin, buf[:])
    if err != os.ERROR_NONE { return }
    s := strings.trim_space(string(buf[:n]))
    n2 := 0
    for c in s { n2 = n2 * 10 + int(c - '0') }
    fmt.println(n2 * 2)
}
